CREATE TABLE IF NOT EXISTS session_period_configs ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, period_number INTEGER NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, break_minute INTEGER NOT NULL DEFAULT 10, FOREIGN KEY (session_id) REFERENCES course_sessions(id) ON DELETE CASCADE ); CREATE TABLE IF NOT EXISTS session_timetable ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, training_date TEXT NOT NULL, period_number INTEGER NOT NULL, subject_id INTEGER NOT NULL, instructor_id INTEGER, location TEXT, is_excluded INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (session_id) REFERENCES course_sessions(id) ON DELETE CASCADE );